# pytest test suite for the API

import pytest
import requests
import os
import yaml

# Read configuration settings from config.yml
config_path = os.path.join(os.path.dirname(__file__), 'config.yml')
with open(config_path, 'r') as file:
    CONFIG = yaml.safe_load(file)

API_HOST = CONFIG['api']['host']
PETSTORE_AUTH = CONFIG['authentication']['petstore_auth']
API_KEY = CONFIG['authentication']['api_key']

# Fixtures for authentication headers
@pytest.fixture
def auth_headers():
    return {
        "Authorization": f"Bearer {PETSTORE_AUTH}",
        "api_key": API_KEY
    }

# Endpoint test suite
@pytest.mark.parametrize("tags, expected_status", [
    (["dog", "cat"], 200),
    ([], 200),  # No tags case
    (["nonexistent"], 200),  # Unknown tag
    (["invalid_tag"], 400)  # Invalid tag value
])
def test_find_pets_by_tags(auth_headers, tags, expected_status):
    """
    Tests the /pet/findByTags endpoint with different tag inputs.
    """
    url = f"{API_HOST}pet/findByTags"
    params = {"tags": tags}
    response = requests.get(url, headers=auth_headers, params=params)

    # Assert response status code
    assert response.status_code == expected_status, f"Unexpected status code {response.status_code}"

    if response.status_code == 200:
        # Validate response schema for successful case
        response_data = response.json()
        assert isinstance(response_data, list)
        for item in response_data:
            assert "name" in item, "Missing 'name' in response item."
            assert "photoUrls" in item, "Missing 'photoUrls' in response item."
    elif response.status_code == 400:
        # Validate response content for invalid tags
        assert "Invalid tag value" in response.text, "Unexpected error message."

    elif response.status_code == 500:
        # Handle unexpected server error (default response)
        assert "Unexpected error" in response.text, "Unexpected error message."
